// A history namespace has no raw fallback, including dates still inside the
// live site's retention window. Every observed hour needs its own zero or set.
$hourEvidence = function(string $from, string $to, array $activity = []): array { $rows = []; for ($h = Engine::ms($from); $h < Engine::ms($to); $h += 3600000) $rows[] = ['hour' => Engine::iso($h), 'complete' => true, 'data' => array_replace(Engine::emptyBucket(), ['activity' => $activity])]; return $rows; };
$historyContext = ['archiveOnly' => true, 'firstSeenComplete' => true, 'firstSeen' => [['visitor_id' => 'v', 'first_date' => '2026-10-10']], 'archives' => []];
$observe = function(array $context, array $observedSite = [], string $from = '2026-10-10T00:00:00Z', string $to = '2026-10-13T00:00:00Z', ?float $asOf = null, string $cohort = '2026-10-10') use ($site, $now): array { $result = Engine::retention(array_replace($site, $observedSite), [], $from, $to, $asOf ?? $now, [], $context); return ((array)$result['cohorts'])[$cohort]['observations']['1']; };
$emptyHistory = $observe($historyContext); $equal($emptyHistory['returned'], null, 'empty snapshot archives do not infer zero returns'); $equal($emptyHistory['coverage'], 0, 'empty snapshot observation coverage unavailable'); $equal($emptyHistory['status'], 'archive_coverage_unavailable', 'snapshot missing-hour reason observable');
$historyContext['archives'] = $hourEvidence('2026-10-11T00:00:00Z', '2026-10-12T00:00:00Z', ['v']); $equal($observe($historyContext)['returned'], 1, '24 proven snapshot hours support exact distinct return'); $equal($observe($historyContext)['coverage'], 1, 'complete snapshot observation coverage');
$missingHour = $historyContext; array_splice($missingHour['archives'], 12, 1); $equal($observe($missingHour)['returned'], null, 'one missing snapshot hour invalidates complete-day claim');
$invalidHour = $historyContext; $invalidHour['archives'][0]['data']['unavailable'] = true; $equal($observe($invalidHour)['returned'], null, 'invalidated archive cannot prove absence or return');
$legacyHour = $historyContext; unset($legacyHour['archives'][0]['data']['activity']); $equal($observe($legacyHour)['returned'], null, 'archive without membership evidence is unavailable');
$zeroHistory = $historyContext; $zeroHistory['archives'] = $hourEvidence('2026-10-11T00:00:00Z', '2026-10-12T00:00:00Z'); $equal($observe($zeroHistory)['returned'], 0, '24 proven empty hours produce a measured zero');
$equal($observe($historyContext, [], '2026-10-10T00:00:00Z', '2026-10-13T00:00:00Z', Engine::ms('2026-10-11T12:00:00Z'))['status'], 'not_mature', 'snapshot as-of prevents later wall clock maturing observation');
$fallContext = ['archiveOnly' => true, 'firstSeenComplete' => true, 'firstSeen' => [['visitor_id' => 'v', 'first_date' => '2026-10-31']], 'archives' => $hourEvidence('2026-11-01T04:00:00Z', '2026-11-02T05:00:00Z', ['v'])];
$fall = $observe($fallContext, ['timezone' => 'America/New_York'], '2026-10-31T04:00:00Z', '2026-11-04T05:00:00Z', Engine::ms('2026-11-05T12:00:00Z'), '2026-10-31'); $equal(count($fallContext['archives']), 25, 'fall-back archive uses 25 actual UTC hours'); $equal($fall['returned'], 1, 'complete 25-hour DST archive readable'); array_pop($fallContext['archives']); $equal($observe($fallContext, ['timezone' => 'America/New_York'], '2026-10-31T04:00:00Z', '2026-11-04T05:00:00Z', Engine::ms('2026-11-05T12:00:00Z'), '2026-10-31')['returned'], null, '24 hours cannot prove 25-hour fall-back day');
$springContext = ['archiveOnly' => true, 'firstSeenComplete' => true, 'firstSeen' => [['visitor_id' => 'v', 'first_date' => '2026-03-07']], 'archives' => $hourEvidence('2026-03-08T05:00:00Z', '2026-03-09T04:00:00Z', ['v'])]; $equal(count($springContext['archives']), 23, 'spring-forward archive uses 23 actual UTC hours'); $equal($observe($springContext, ['timezone' => 'America/New_York'], '2026-03-07T05:00:00Z', '2026-03-11T04:00:00Z', Engine::ms('2026-03-12T12:00:00Z'), '2026-03-07')['returned'], 1, 'complete 23-hour DST archive readable');
$offsetContext = $historyContext; $offsetContext['archives'] = $hourEvidence('2026-10-10T18:00:00Z', '2026-10-12T00:00:00Z', ['v']); $equal($observe($offsetContext, ['timezone' => 'Asia/Kolkata'], '2026-10-09T18:30:00Z', '2026-10-12T18:30:00Z')['returned'], null, 'half-hour midnight cannot be reconstructed from hourly membership'); $equal($observe($offsetContext, ['timezone' => 'Asia/Kathmandu'], '2026-10-09T18:15:00Z', '2026-10-12T18:15:00Z')['coverage'], 0, 'quarter-hour midnight coverage is unavailable');
